CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK (role IN ('admin','reception','cashier','inventory','readonly')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number text UNIQUE NOT NULL, floor text NOT NULL DEFAULT '', type text NOT NULL DEFAULT 'standard', capacity integer NOT NULL CHECK (capacity > 0), base_price numeric(12,2) NOT NULL DEFAULT 0 CHECK (base_price >= 0), status text NOT NULL DEFAULT 'available' CHECK (status IN ('available','maintenance','out_of_service')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, document text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guest_id uuid NOT NULL REFERENCES guests(id), room_id uuid NOT NULL REFERENCES rooms(id), checkin date NOT NULL, checkout date NOT NULL, adults integer NOT NULL DEFAULT 1 CHECK (adults > 0), children integer NOT NULL DEFAULT 0 CHECK (children >= 0), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','confirmed','cancelled','no_show','checked_in','checked_out')), source text NOT NULL DEFAULT 'direct', price_per_night numeric(12,2) NOT NULL DEFAULT 0, total_price numeric(12,2) NOT NULL DEFAULT 0, deposit numeric(12,2) NOT NULL DEFAULT 0, due_date date, notes text NOT NULL DEFAULT '', created_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (checkout > checkin), CHECK (deposit >= 0));
CREATE INDEX IF NOT EXISTS reservations_dates_idx ON reservations (room_id, checkin, checkout);
ALTER TABLE reservations ADD CONSTRAINT reservations_no_overlap EXCLUDE USING gist (room_id WITH =, daterange(checkin, checkout, '[)') WITH &&) WHERE (status NOT IN ('cancelled','no_show'));
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_id uuid REFERENCES reservations(id), amount numeric(12,2) NOT NULL CHECK (amount > 0), method text NOT NULL CHECK (method IN ('cash','transfer','debit','credit','booking','other')), paid_at timestamptz NOT NULL DEFAULT now(), notes text NOT NULL DEFAULT '', created_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS cash_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK (kind IN ('income','expense','withdrawal','adjustment')), amount numeric(12,2) NOT NULL CHECK (amount > 0), method text NOT NULL CHECK (method IN ('cash','transfer','debit','credit','booking','other')), description text NOT NULL, movement_date date NOT NULL DEFAULT CURRENT_DATE, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cash_closures (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), closure_date date UNIQUE NOT NULL, opening_balance numeric(12,2) NOT NULL DEFAULT 0, counted_balance numeric(12,2), closed_by uuid REFERENCES users(id), closed_at timestamptz, reopened_by uuid REFERENCES users(id), reopened_at timestamptz);
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, category text NOT NULL DEFAULT 'general', unit text NOT NULL DEFAULT 'unidad', current_stock numeric(12,3) NOT NULL DEFAULT 0, minimum_stock numeric(12,3) NOT NULL DEFAULT 0, cost numeric(12,2) NOT NULL DEFAULT 0, supplier text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS inventory_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), kind text NOT NULL CHECK (kind IN ('purchase','consumption','adjustment')), quantity numeric(12,3) NOT NULL CHECK (quantity <> 0), unit_cost numeric(12,2) NOT NULL DEFAULT 0, reference text NOT NULL DEFAULT '', created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id), action text NOT NULL, entity text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
